/* Staff presence uses server-timed 90-second leases, independent of saved workspace data. */
(function(){'use strict';
const api=()=>window.CAGE_BACKEND,profile=()=>api()?.currentProfile?.();
const CAGE_IDLE_MS=10*60*1000;
const mobileDevice=()=>navigator.userAgentData?.mobile===true||/Android|iPhone|iPad|iPod/i.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
const sid=crypto.randomUUID(); // Each document gets its own lease; closing one tab cannot hide another.
let rows=[],lastSuccess=0,lastActivity=Date.now(),running=false,beatPending=false,stopped=true,generation=0,timer=null,drawPending=false;
const labels={online:'Online',away:'Away',offline:'Offline',unknown:'Status unavailable'};
const button=document.createElement('button');button.type='button';button.id='cage-online-button';button.className='secondary-button';button.hidden=true;document.querySelector('.topbar-actions')?.prepend(button);
const dialog=document.createElement('dialog');dialog.id='cage-online-dialog';dialog.className='app-dialog';dialog.setAttribute('aria-labelledby','cage-online-title');dialog.innerHTML='<div class="dialog-heading"><h2 id="cage-online-title">Team availability</h2><button type="button" class="secondary-button" data-presence-close>Close</button></div><p class="cage-online-note">Online means the Hub is open and recently active. Away means ten minutes without activity in the Hub. On phones and tablets, leaving the Hub also means Away. Desktop background tabs can remain online until the ten-minute timer expires, provided the browser keeps them connected. Active Hub time is estimated for daily totals in an admin-only weekly report. Away time is excluded; the online grace period, including desktop background time, can count toward the estimate. Multiple devices count once. This is not attendance or productivity tracking.</p><p id="cage-online-error" role="status"></p><ul id="cage-online-list"></ul><p class="cage-online-note">Updates about every 30 seconds. Closed or disconnected sessions expire within 90 seconds.</p><button type="button" class="secondary-button" data-presence-refresh>Refresh status</button>';document.body.append(dialog);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statusDialog=document.createElement('dialog');statusDialog.id='cage-status-dialog';statusDialog.className='app-dialog';statusDialog.setAttribute('aria-labelledby','cage-status-title');document.body.append(statusDialog);
const reportDialog=document.createElement('dialog');reportDialog.id='cage-presence-report-dialog';reportDialog.className='app-dialog';document.body.append(reportDialog);
const actions=document.createElement('div');actions.className='cage-status-actions';actions.innerHTML='<button type="button" class="secondary-button" id="cage-set-status">Set your status</button><button type="button" class="secondary-button" id="cage-weekly-report" hidden>Weekly online summary</button>';dialog.querySelector('.dialog-heading').after(actions);
function own(){return rows.find(r=>r.id===profile()?.id)||{};}
let recentStatuses=[];
const expiryLabels={'30m':'30 minutes','1h':'1 hour','4h':'4 hours',today:'Today (CAT)',week:'This week (CAT)',never:"Don't clear automatically",custom:'Choose date and time'};
function expiryFields(){const f=statusDialog.querySelector('form');const custom=f.elements.clear_after.value==='custom';f.querySelector('[data-expiry-field]').hidden=!custom;f.elements.expires_local.required=custom;}
function drawRecent(){statusDialog.querySelector('[data-recents]').innerHTML=recentStatuses.length?recentStatuses.map((r,i)=>`<div class="cage-recent-row"><button type="button" class="secondary-button" data-recent="${i}"><span>${esc(r.emoji)}</span> ${esc(r.message)} <small>— ${esc(expiryLabels[r.clear_after]||'Today (CAT)')}</small></button><button type="button" class="secondary-button" data-forget="${i}" aria-label="Remove ${esc(r.message||r.emoji)} from recent statuses">×</button></div>`).join(''):'<p class="cage-online-note">Your saved statuses will appear here. Only you can see this history.</p>';}
async function showStatus(){statusDialog.innerHTML='<p role="status">Loading your status…</p><button type="button" data-status-close class="secondary-button">Close</button>';statusDialog.showModal();try{const settings=await api().presenceStatusSettings();if(!statusDialog.open)return;const me=settings.current||own();const active=!me.expires_at||new Date(me.expires_at)>new Date();recentStatuses=settings.recent||[];statusDialog.innerHTML=`<div class="dialog-heading"><h2 id="cage-status-title">Set your status</h2><button type="button" class="secondary-button" data-status-close>Close</button></div><form id="cage-status-form"><label for="cage-status-message">What's your status?</label><div class="cage-status-entry"><button type="button" class="secondary-button" data-emoji-toggle aria-label="Choose an emoji" aria-expanded="false">${esc(active&&me.emoji||'☺')}</button><input id="cage-status-message" name="message_value" maxlength="100" value="${esc(active&&me.message||'')}" placeholder="What's your status?"></div><div data-emoji-picker hidden><label class="field"><span>Choose or paste any emoji</span><input name="emoji_value" maxlength="32" value="${esc(active&&me.emoji||'')}" placeholder="Paste an emoji"></label></div><label class="field"><span>Clear status after</span><select name="clear_after">${Object.entries(expiryLabels).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label><label class="field" data-expiry-field hidden><span>Clear on (Malawi time, CAT / UTC+02:00)</span><input type="datetime-local" step="1" name="expires_local"></label><h3>Recent</h3><div data-recents></div><p class="cage-online-note">Reusing a status starts its duration again. A status previously set to a specific date defaults to Today.</p><label class="field"><span>Availability</span><select name="availability_mode"><option value="auto">Automatic — green while active</option><option value="away">Set myself Away</option></select></label><p class="cage-online-note">Your message does not change your availability. Manual Away stays set until you choose Automatic.</p><p class="form-error" role="alert"></p><div class="dialog-actions"><button type="button" class="secondary-button" data-status-clear>Clear status</button><button class="primary-button" type="submit">Save status</button></div></form>`;const f=statusDialog.querySelector('form');f.elements.availability_mode.value=me.mode||'auto';f.elements.clear_after.value=active&&(me.message||me.emoji)?(me.expires_at?'custom':'never'):'today';if(active&&me.expires_at)f.elements.expires_local.value=new Date(new Date(me.expires_at).getTime()+7200000).toISOString().slice(0,19);expiryFields();drawRecent();f.elements.message_value.focus();}catch(e){statusDialog.innerHTML=`<p role="alert">${esc(e.message||'Could not load status settings')}</p><button type="button" class="secondary-button" data-status-close>Close</button>`;}}
actions.querySelector('#cage-set-status').addEventListener('click',showStatus);
statusDialog.addEventListener('change',e=>{if(e.target.name==='clear_after')expiryFields();});
statusDialog.addEventListener('input',e=>{if(e.target.name==='emoji_value')statusDialog.querySelector('[data-emoji-toggle]').textContent=e.target.value||'☺';});
statusDialog.addEventListener('click',async e=>{if(e.target.closest('[data-status-close]')){statusDialog.close();return;}const f=statusDialog.querySelector('form');if(!f)return;const toggle=e.target.closest('[data-emoji-toggle]');if(toggle){window.CAGE_EMOJI.open(toggle,emoji=>{f.elements.emoji_value.value=emoji;toggle.textContent=emoji;return true;});}const emoji=e.target.closest('[data-status-emoji]');if(emoji){f.elements.emoji_value.value=emoji.dataset.statusEmoji;f.querySelector('[data-emoji-toggle]').textContent=emoji.dataset.statusEmoji;f.querySelector('[data-emoji-picker]').hidden=true;f.querySelector('[data-emoji-toggle]').setAttribute('aria-expanded','false');f.elements.message_value.focus();}const recent=e.target.closest('[data-recent]');if(recent){const r=recentStatuses[Number(recent.dataset.recent)];f.elements.message_value.value=r.message;f.elements.emoji_value.value=r.emoji;f.querySelector('[data-emoji-toggle]').textContent=r.emoji||'☺';f.elements.clear_after.value=r.clear_after;expiryFields();}const forget=e.target.closest('[data-forget]');if(forget){const r=recentStatuses[Number(forget.dataset.forget)];forget.disabled=true;try{await api().presenceStatusForget(r.emoji,r.message);recentStatuses=recentStatuses.filter(x=>x!==r);drawRecent();}catch(err){f.querySelector('.form-error').textContent=err.message;forget.disabled=false;}}if(e.target.closest('[data-status-clear]')){f.elements.emoji_value.value='';f.elements.message_value.value='';f.elements.clear_after.value='never';expiryFields();f.requestSubmit();}});
statusDialog.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=f.querySelector('[type=submit]'),error=f.querySelector('.form-error');if(b.disabled)return;b.disabled=true;error.textContent='';try{const values=Object.fromEntries(new FormData(f));values.expires_on=values.clear_after==='custom'?new Date(values.expires_local+'+02:00').toISOString():null;delete values.expires_local;await api().presenceStatus(values);await beat();statusDialog.close();}catch(e){error.textContent=e.message||'Could not save status';}finally{b.disabled=false;}});
const hours=n=>{const seconds=Math.max(0,Math.floor(Number(n)||0));return `${Math.floor(seconds/3600)}h ${String(Math.floor(seconds/60)%60).padStart(2,'0')}m ${String(seconds%60).padStart(2,'0')}s`;};
async function report(week){const target=reportDialog.querySelector('[data-report-content]');target.textContent='Loading weekly summary…';try{const data=await api().presenceWeek(week);target.innerHTML=`<p class="cage-online-note">${esc(data.week_start)} – ${esc(data.week_end)} · CAT. Tracking began ${esc(new Date(data.tracking_started_at).toLocaleString('en-GB',{timeZone:'Africa/Blantyre'}))}. Earlier dates are untracked; the first week may be partial. Daily durations are shown to whole seconds; the displayed weekly total adds those daily figures.</p><div class="cage-report-scroll"><table><thead><tr><th>Member</th>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun','Total'].map(d=>`<th>${d}</th>`).join('')}</tr></thead><tbody>${data.members.map(m=>`<tr><th scope="row">${esc(m.name)}</th>${m.days.map(d=>`<td>${hours(d.seconds)}</td>`).join('')}<td><strong>${hours(m.days.reduce((total,d)=>total+Math.floor(Number(d.seconds)||0),0))}</strong></td></tr>`).join('')}</tbody></table></div>`;}catch(e){target.textContent=e.message||'Summary unavailable';}}
actions.querySelector('#cage-weekly-report').addEventListener('click',()=>{if(profile()?.role!=='admin')return;const d=new Date(Date.now()+7200000);d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));const week=d.toISOString().slice(0,10);reportDialog.innerHTML=`<div class="dialog-heading"><h2>Weekly active Hub time</h2><button type="button" class="secondary-button" data-report-close>Close</button></div><p class="cage-online-note">Admin only. Estimated active time, not attendance. The completed Monday–Sunday week is emailed to active admins after Monday 00:05 CAT. Current-week totals are provisional.</p><form><label class="field"><span>Week starting Monday (CAT)</span><input name="week" type="date" required value="${week}"></label><button class="secondary-button">View week</button></form><div data-report-content aria-live="polite"></div>`;reportDialog.showModal();report(week);});
reportDialog.addEventListener('click',e=>{if(e.target.closest('[data-report-close]'))reportDialog.close();});reportDialog.addEventListener('submit',e=>{e.preventDefault();report(e.target.elements.week.value);});
function fresh(){return !stopped&&lastSuccess&&navigator.onLine&&Date.now()-lastSuccess<90000;}
function status(id){return fresh()?rows.find(r=>r.id===id||r.member_id===id)?.status||'unknown':'unknown';}
function draw(){drawPending=false;const known=fresh();button.hidden=stopped||!profile()||profile().role==='shared';const online=known?rows.filter(r=>r.status==='online').length:0;button.innerHTML=`<span class="cage-presence-dot ${known?'online':'unknown'}" aria-hidden="true"></span>${known?online+' online':'Status unavailable'}`;button.title='View team availability';
 for(const el of document.querySelectorAll('[data-presence-member]')){const value=status(el.dataset.presenceMember);const details=fresh()?JSON.stringify(rows.find(r=>r.id===el.dataset.presenceMember||r.member_id===el.dataset.presenceMember)||{}):'';if(el.dataset.presenceState===value&&el.dataset.presenceDetails===details)continue;el.dataset.presenceDetails=details;el.dataset.presenceState=value;const r=rows.find(r=>r.id===el.dataset.presenceMember||r.member_id===el.dataset.presenceMember),custom=fresh()?[r?.emoji,r?.message].filter(Boolean).join(' '):'';const label=labels[value]+(custom?' · '+custom:'');if(el.classList.contains('cage-presence-label'))el.innerHTML=`<span class="cage-presence-dot ${value}" aria-hidden="true"></span>${esc(label)}`;else{el.querySelector('.cage-presence-dot')?.remove();const dot=document.createElement('span');dot.className='cage-presence-dot '+value;dot.setAttribute('role','img');dot.setAttribute('aria-label',label);dot.title=label;el.append(dot);el.querySelector('.cage-status-emoji')?.remove();if(fresh()&&r?.emoji){const emoji=document.createElement('span');emoji.className='cage-status-emoji';emoji.textContent=r.emoji;emoji.title=custom;emoji.setAttribute('aria-label',custom);el.append(emoji);}}}
 document.getElementById('cage-weekly-report').hidden=profile()?.role!=='admin';if(dialog.open){document.getElementById('cage-online-error').textContent=known?'':'Status could not be loaded. Check your connection or try Refresh status.';document.getElementById('cage-online-list').innerHTML=known?[...rows].sort((a,b)=>({online:0,away:1,offline:2}[a.status]-{online:0,away:1,offline:2}[b.status])||a.name.localeCompare(b.name)).map(r=>`<li><span class="cage-presence-dot ${r.status}" aria-hidden="true"></span><strong>${esc(r.name)}${r.id===profile()?.id?' (you)':''}<small class="cage-status-message">${esc([r.emoji,r.message].filter(Boolean).join(' '))}</small></strong><span>${labels[r.status]}</span></li>`).join(''):'';}}
function scheduleDraw(){if(!drawPending){drawPending=true;requestAnimationFrame(draw);}}
async function beat(){if(stopped||!profile())return;if(running){beatPending=true;return;}const token=generation;running=true;try{if(!navigator.onLine)throw Error('offline');const data=await api().presenceHeartbeat(sid,(mobileDevice()&&document.hidden)||Date.now()-lastActivity>=CAGE_IDLE_MS?'away':'online');if(token!==generation)return;rows=data;lastSuccess=Date.now();window.dispatchEvent(new Event("cage:presence-updated"));}catch{if(token===generation)lastSuccess=0;}finally{running=false;draw();if(beatPending){beatPending=false;queueMicrotask(beat);}}}
async function stop(){const wasActive=!stopped;stopped=true;generation++;clearInterval(timer);lastSuccess=0;rows=[];dialog.close();statusDialog.close();reportDialog.close();draw();if(wasActive&&profile())await Promise.race([api().presenceHeartbeat(sid,'offline').catch(()=>{}),new Promise(resolve=>setTimeout(resolve,1200))]);}
function start(){generation++;stopped=!profile()||profile().active===false||profile().role==='shared';lastSuccess=0;rows=[];lastActivity=Date.now();clearInterval(timer);if(!stopped){beat();timer=setInterval(()=>{if(!profile()){stop();return;}beat();},30000);}draw();}
button.addEventListener('click',()=>{dialog.showModal();draw();beat();});dialog.querySelector('[data-presence-close]').addEventListener('click',()=>dialog.close());dialog.querySelector('[data-presence-refresh]').addEventListener('click',()=>beat());
for(const event of ['pointerdown','pointermove','keydown','touchstart','touchmove','wheel'])document.addEventListener(event,()=>{const wasAway=Date.now()-lastActivity>=CAGE_IDLE_MS;lastActivity=Date.now();if(wasAway)beat();},{passive:true});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)lastActivity=Date.now();beat();});window.addEventListener('online',beat);window.addEventListener('offline',()=>{lastSuccess=0;draw();});window.addEventListener('pagehide',()=>{stop();});window.addEventListener('pageshow',e=>{if(e.persisted)start();});window.addEventListener('cage:session-ready',start);
// Paint only newly rendered availability targets; do not re-render chat or disturb scrolling/drafts.
new MutationObserver(records=>{if(records.some(r=>[...r.addedNodes].some(n=>n.nodeType===1&&(n.matches?.('[data-presence-member]')||n.querySelector?.('[data-presence-member]')))))scheduleDraw();}).observe(document.body,{childList:true,subtree:true});
window.CAGE_PRESENCE={stop,status,refresh:beat};if(profile())start();
})();
